$wfFolderOptions = static function(string $selected = '', string $exclude = '') use ($wfFolderTree, $wfEsc, $wfI, $wfF): void {
    echo '<option value="">'.$wfEsc($wfI('Ohne Ordner / oberste Ebene')).'</option>';
    $blocked=$wfFolderTree->blockedParents($exclude);$labels=$wfFolderTree->labels();
    if($selected!==''&&(!array_key_exists($selected,$labels)||isset($blocked[$selected])))echo '<option value="'.$wfEsc($selected).'" selected>'.$wfEsc($wfF('Zuordnung prüfen: {value}',['value'=>$labels[$selected]??$selected])).'</option>';
    foreach ($wfFolderTree->rows() as $folder) {
        if (isset($blocked[$folder['id']])) continue;
        echo '<option value="'.$wfEsc($folder['id']).'"'.($selected === $folder['id'] ? ' selected' : '').'>'.$wfEsc($labels[$folder['id']]).'</option>';
    }
};
$wfProvenance = static function(array $provenance) use ($wfEsc, $wfI): void {
    if (!$provenance) { echo '<p class="dwf-muted">'.$wfEsc($wfI('Eigene Vorlage ohne hinterlegte externe Quellenangabe.')).'</p>'; return; }
    $labels = ['title' => $wfI('Referenz'), 'url' => $wfI('Quelle'), 'licence' => $wfI('Nutzungsbedingungen'), 'licence_url' => $wfI('Lizenzquelle'), 'attribution' => $wfI('Quellennachweis'), 'adaptation' => $wfI('Bearbeitung'), 'verified_at' => $wfI('Quellenstand')];
    echo '<dl class="dwf-provenance">';
    foreach ($provenance as $key => $value) {
        if (!is_scalar($value) || $value === '') continue;
        echo '<dt>'.$wfEsc($labels[$key] ?? $key).'</dt><dd>';
        if (in_array($key, ['url', 'licence_url'], true) && preg_match('~^https?://~i', (string)$value)) echo '<a href="'.$wfEsc($value).'" target="_blank" rel="noopener noreferrer">'.$wfEsc($value).'</a>';
        else echo nl2br($wfEsc($value));
        echo '</dd>';
    }
    echo '</dl>';
};
$wfFieldRow = static function(array $field, int|string $index,int $total=0,?array $original=null,bool $focus=false) use ($wfEsc, $wfTypes, $wfRiskProfiles, $wfI, $wfF,$wfHidden): void {
