        <div class="dwf-grid"><label><?= $wfEsc($wfI('Beschriftung')) ?><textarea class="form-control" name="<?= $wfEsc($prefix) ?>[label]" data-dwf-character-limit="200" rows="2" required data-dwf-label <?= $focus?'autofocus':'' ?>><?= $wfEsc($field['label'] ?? '') ?></textarea><small><?= $wfEsc($wfF('Bis zu {count} Zeichen.',['count'=>200])) ?></small></label><details class="dwf-field-settings" <?= is_int($index)&&!preg_match('/^[a-z][a-z0-9_]{0,63}$/D',(string)($field['key']??''))?'open':'' ?>><summary><?= $wfEsc($wfI('Weitere Feldeinstellungen')) ?></summary><label><?= $wfEsc($wfI('Feldkennung')) ?><input class="form-control" name="<?= $wfEsc($prefix) ?>[key]" maxlength="64" pattern="[a-z][a-z0-9_]{0,63}" required value="<?= $wfEsc($field['key'] ?? '') ?>" data-dwf-key><small><?= $wfEsc($wfI('Stabile Kennung, z. B. arbeitsbereich; Kleinbuchstaben, Ziffern, Unterstrich.')) ?></small></label></details></div>
        <div class="dwf-grid"><label><?= $wfEsc($wfI('Feldart')) ?><select class="form-control" name="<?= $wfEsc($prefix) ?>[type]" data-dwf-type><?php if(!array_key_exists($fieldType,$wfTypes)):?><option value="<?= $wfEsc($fieldType) ?>" selected><?= $wfEsc($wfF('Feldart prüfen: {value}',['value'=>$fieldType])) ?></option><?php endif; foreach ($wfTypes as $type => $label): ?><option value="<?= $wfEsc($type) ?>" <?= $fieldType === $type ? 'selected' : '' ?>><?= $wfEsc($label) ?></option><?php endforeach ?></select></label><label class="dwf-check"><input class="check" type="checkbox" name="<?= $wfEsc($prefix) ?>[required]" value="1" <?= !empty($field['required']) ? 'checked' : '' ?>> <?= $wfEsc($wfI('Pflichtfeld bei Einreichung')) ?></label></div>
        <label><?= $wfEsc($wfI('Ausfüllhilfe')) ?><textarea class="form-control" name="<?= $wfEsc($prefix) ?>[help]" rows="2" data-dwf-character-limit="2000"><?= $wfEsc($field['help'] ?? '') ?></textarea><small><?= $wfEsc($wfF('Bis zu {count} Zeichen.',['count'=>2000])) ?></small></label>
        <label data-dwf-options><?= $wfEsc($wfI('Auswahlmöglichkeiten')) ?><textarea class="form-control" name="<?= $wfEsc($prefix) ?>[options]" rows="3" placeholder="<?= $wfEsc($wfI('Je Zeile eine Möglichkeit')) ?>"><?= $wfEsc($options) ?></textarea><small><?= $wfEsc($wfI('Nur bei Feldart „Auswahl“; eine Möglichkeit je Zeile.')) ?></small></label>
