        <label data-dwf-profile-setting><?= $wfEsc($wfI('Risikomatrix-Profil')) ?><select class="form-control" name="<?= $wfEsc($prefix) ?>[matrix_profile]" data-dwf-matrix-profile><?php if(!array_key_exists($profileValue,$wfRiskProfiles)):?><option value="<?= $wfEsc($profileValue) ?>" selected><?= $wfEsc($wfF('Profil prüfen: {value}',['value'=>$profileValue])) ?></option><?php endif; foreach ($wfRiskProfiles as $profileId => $profile): ?><option value="<?= $wfEsc($profileId) ?>" <?= $profileValue === $profileId ? 'selected' : '' ?>><?= $wfEsc($profileId === '' ? $wfI('Neutral · ohne Farbstufen') : $wfI('Matrix der Referenzvorlage')) ?></option><?php endforeach ?></select><small><?= $wfEsc($wfI('Das Profil gilt für dieses Gefährdungsregister. Vorhandene Dokumente behalten das Profil ihrer ursprünglichen Vorlagenfassung.')) ?></small></label>
    </fieldset>
