$wfMatrix = static function(string $name, string $id, mixed $value, bool $editable) use ($wfEsc, $wfI,$wfF): void {
    $likelihood=is_array($value)&&is_scalar($value['likelihood']??null)?(string)$value['likelihood']:'';$severity=is_array($value)&&is_scalar($value['severity']??null)?(string)$value['severity']:'';$complete=preg_match('/^[1-5]$/D',$likelihood)&&preg_match('/^[1-5]$/D',$severity);
    ?><fieldset class="dwf-matrix" data-dwf-matrix><legend><?= $wfEsc($wfI('Risikomatrix (5 × 5)')) ?></legend><div class="dwf-grid"><?php foreach(['likelihood'=>$wfI('Wahrscheinlichkeit'),'severity'=>$wfI('Schadensschwere')]as$axis=>$label):?><label><?= $wfEsc($label) ?><select class="form-control" id="<?= $wfEsc($id.($axis==='likelihood'?'':'-severity')) ?>" name="<?= $wfEsc($name.'['.$axis.']') ?>" data-dwf-axis="<?= $axis ?>" <?= !$editable?'disabled':'' ?>><option value=""><?= $wfEsc($wfI('Noch offen')) ?></option><?php for($level=1;$level<=5;$level++):?><option value="<?= $level ?>" <?= ($axis==='likelihood'?$likelihood:$severity)===(string)$level?'selected':'' ?>><?= $axis==='severity'?chr(64+$level).' ('.$level.')':$level ?></option><?php endfor ?></select></label><?php endforeach ?></div>
    <div class="dwf-matrix-table-wrap" data-dwf-matrix-grid><table class="table dwf-matrix-table"><caption><?= $wfEsc($wfI('Risikomatrix · R = S × L')) ?></caption><thead><tr><th scope="col">S / L</th><?php for($l=1;$l<=5;$l++):?><th scope="col"><?= $l ?></th><?php endfor ?></tr></thead><tbody><?php for($s=5;$s>=1;$s--):?><tr><th scope="row"><?= chr(64+$s) ?></th><?php for($l=1;$l<=5;$l++):$band=\Kulturhus\Verein\DocumentWorkflow\RiskMatrix::band($l*$s);?><td><button type="button" class="btn dwf-matrix-cell" style="background:<?= $band['background'] ?>!important;color:#000!important" data-dwf-risk-likelihood="<?= $l ?>" data-dwf-risk-severity="<?= $s ?>" aria-label="<?= $wfEsc($wfF('{severity} × {likelihood}: Risikowert {score}{band}',['severity'=>chr(64+$s),'likelihood'=>$l,'score'=>$l*$s,'band'=>', '.$band['label']])) ?>" aria-pressed="<?= $likelihood===(string)$l&&$severity===(string)$s?'true':'false' ?>" <?= !$editable?'disabled':'' ?>><?= $l*$s ?></button></td><?php endfor ?></tr><?php endfor ?></tbody></table></div>
    <output class="dwf-risk-score" data-dwf-risk-score aria-live="polite"><?= $wfEsc($complete?$wfF('Risikowert: {score} ({likelihood} × {severity})',['score'=>(int)$likelihood*(int)$severity,'likelihood'=>$likelihood,'severity'=>$severity]):$wfI('Bewertung noch offen')) ?></output><p class="dwf-matrix-note"><?= $wfEsc($wfI(\Kulturhus\Verein\DocumentWorkflow\RiskMatrix::NOTE)) ?></p></fieldset><?php
};
